60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	};
64	
65	const sumBasePremiums = (items: Item[]): number =>
66	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
67	
